:root {
  /* Colors */
  --color-paper-canvas: #ffffff;
  --color-fog-panel: #f4f4f5;
  --color-carbon-panel: #1a1a1d;
  --color-onyx-panel: #101013;
  --color-jet-glass: #0a0a0c99;
  --color-ink: #000000;
  --color-jet-ink: #0a0a0c;
  --color-slate-caption: #71717a;
  --color-ash-rule: #a1a1aa;
  --color-mist-hairline: #e4e4e7;
  --color-pewter-border: #ccccd5;
  --color-signal-lime: #f1ff5c;
  --color-keylime-readout: #f4ff7d;

  /* Typography — Font Families */
  --font-geist-sans: "Geist", "GeistSans", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-geist-mono: "Geist Mono", "GeistMono", ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;

  /* Typography — Scale */
  --text-small: 12px;
  --leading-small: 1;
  --tracking-small: 0.24px;
  --text-caption: 15px;
  --leading-caption: 1.4;
  --tracking-caption: 0.3px;
  --text-body-sm: 15px;
  --leading-body-sm: 1.5;
  --tracking-body-sm: 0px;
  --text-body: 16px;
  --leading-body: 1.5;
  --tracking-body: 0px;
  --text-body-lg: 18px;
  --leading-body-lg: 1.5;
  --tracking-body-lg: 0px;
  --text-subheading: 22px;
  --leading-subheading: 1.5;
  --tracking-subheading: -0.22px;
  --text-heading-sm: 32px;
  --leading-heading-sm: 1.2;
  --tracking-heading-sm: -0.32px;
  --text-heading: 44px;
  --leading-heading: 1.25;
  --tracking-heading: 0px;
  --text-heading-lg: 52px;
  --leading-heading-lg: 1.1;
  --tracking-heading-lg: -1.56px;
  --text-display: 80px;
  --leading-display: 1.1;
  --tracking-display: -2.4px;

  /* Typography — Weights */
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;
  --font-weight-bold: 700;

  /* Spacing */
  --spacing-2: 2px;
  --spacing-4: 4px;
  --spacing-6: 6px;
  --spacing-8: 8px;
  --spacing-10: 10px;
  --spacing-12: 12px;
  --spacing-16: 16px;
  --spacing-20: 20px;
  --spacing-24: 24px;
  --spacing-32: 32px;
  --spacing-40: 40px;
  --spacing-48: 48px;
  --spacing-60: 60px;
  --spacing-64: 64px;
  --spacing-80: 80px;
  --spacing-120: 120px;

  /* Layout */
  --page-max-width: 1440px;
  --section-gap: 120px;
  --card-padding: 32px;
  --element-gap: 16px;

  /* Border Radius */
  --radius-sm: 2px;
  --radius-md: 4px;
  --radius-lg: 8px;

  /* Named Radii */
  --radius-buttons: 4px;
  --radius-inputs: 4px;
  --radius-cards: 8px;
  --radius-images: 8px;
  --radius-nav: 8px;
  --radius-tags: 2px;
  --radius-badges: 2px;
  --radius-small-elements: 2px;

  /* Shadows */
  --shadow-subtle: 0px 0px 5px 0px rgb(128, 128, 128);

  /* Surfaces */
  --surface-paper-canvas: #ffffff;
  --surface-fog-panel: #f4f4f5;
  --surface-onyx-panel: #101013;
  --surface-carbon-panel: #1a1a1d;
  --surface-jet-glass: #0a0a0c99;
}

